window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Oh-4gmbxa_s","speaker":"John Dramani Mahama","role":"President","country":"Ghana","region":"Africa","url":"https://www.youtube.com/watch?v=Oh-4gmbxa_s","date":"20260924","title":"🇬🇭 Ghana - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1608,"words":3266,"counts":{"claims":41,"promises":2,"attacks":1},"topics":[{"topic":"Israel-Gaza","share":0.0811,"seconds":130},{"topic":"UN Security Council","share":0.0477,"seconds":77},{"topic":"Ghana economy","share":0.0473,"seconds":76},{"topic":"Climate change","share":0.0457,"seconds":74},{"topic":"Ghana history","share":0.0439,"seconds":71},{"topic":"UN leadership","share":0.0434,"seconds":70},{"topic":"UNGA session","share":0.043,"seconds":69},{"topic":"Ghana healthcare","share":0.0422,"seconds":68},{"topic":"African liberation","share":0.0419,"seconds":67},{"topic":"African minerals","share":0.0414,"seconds":67},{"topic":"Cuba","share":0.0411,"seconds":66},{"topic":"Ghana democracy","share":0.0409,"seconds":66},{"topic":"Ghana infrastructure","share":0.0407,"seconds":66},{"topic":"Climate finance","share":0.0405,"seconds":65},{"topic":"UN Security Council reform","share":0.0394,"seconds":63},{"topic":"Transatlantic trafficking","share":0.0388,"seconds":62},{"topic":"Global unity","share":0.0388,"seconds":62},{"topic":"African Union","share":0.0387,"seconds":62},{"topic":"African reparations","share":0.0386,"seconds":62},{"topic":"Xenophobia","share":0.0386,"seconds":62},{"topic":"Transatlantic slave trade","share":0.0384,"seconds":62},{"topic":"Global health architecture","share":0.0379,"seconds":61},{"topic":"Ghanaian culture","share":0.0378,"seconds":61},{"topic":"Ceremony","share":0.0121,"seconds":19}],"timeline":[[1,70,"UNGA session"],[72,142,"UN leadership"],[144,214,"Ghana history"],[216,277,"Ghanaian culture"],[278,340,"Xenophobia"],[341,403,"Transatlantic trafficking"],[405,467,"Transatlantic slave trade"],[472,534,"African reparations"],[535,612,"UN Security Council"],[614,678,"UN Security Council reform"],[678,745,"African minerals"],[746,806,"Israel-Gaza"],[807,877,"Israel-Gaza"],[878,944,"Cuba"],[945,1019,"Climate change"],[1020,1085,"Climate finance"],[1086,1147,"Global health architecture"],[1148,1224,"Ghana economy"],[1226,1292,"Ghana infrastructure"],[1293,1361,"Ghana healthcare"],[1362,1428,"Ghana democracy"],[1435,1497,"African Union"],[1499,1566,"African liberation"],[1568,1630,"Global unity"],[1631,1650,"Ceremony"]],"stances":{"UNGA session":"John Dramani Mahama congratulates the President on their election to preside over the 81st session of the United Nations General Assembly.","UN leadership":"John Dramani Mahama commends the outgoing UN Secretary General for his dedicated service over the last 10 years.","Ghana history":"John Dramani Mahama introduces himself as the President of Ghana and recounts his birthplace and family lineage to emphasize the historical and cultural roots behind his leadership.","Ghanaian culture":"John Dramani Mahama describes his personal linguistic background and argues that language and cultural origin provide dignity and a sense of belonging to all people.","Xenophobia":"John Dramani Mahama argues that weaponized belonging leads to discrimination and war, while affirming the UN's founding principle that all humans are equal regardless of race or origin.","Transatlantic trafficking":"John Dramani Mahama asserts that the transatlantic trafficking and enslavement of Africans must be fully recognized as a crime against humanity to enable healing through truth and repair.","Transatlantic slave trade":"John Dramani Mahama asserts that the transatlantic slave trade was a gravest crime against humanity that built modern Western empires while causing generational trauma in Africa, and notes Ghana's successful resolution on this issue.","African reparations":"John Dramani Mahama states that the resolution on reparative justice was adopted due to ongoing structural legacies of historic crimes and welcomes positive moves from specific European nations to join the dialogue.","UN Security Council":"John Dramani Mahama argues that Africa's lack of permanent representation on the UN Security Council is fundamentally unacceptable and inconsistent with the principle of sovereign equality.","UN Security Council reform":"John Dramani Mahama asserts that UN Security Council reform is essential for the legitimacy and survival of the United Nations rather than a favor to Africa.","African minerals":"John Dramani Mahama asserts that Africa must move beyond being a passive source of raw materials and instead process its own critical minerals to build local industries and create jobs.","Israel-Gaza":"John Dramani Mahama describes the situation in Gaza and the West Bank as a crisis of credibility and an ongoing persecution.","Cuba":"John Dramani Mahama calls for the immediate lifting of the economic embargo on Cuba and urges global support for its new programs.","Climate change":"John Dramani Mahama asserts that climate change is an undeniable reality evidenced by extreme weather phenomena and represents a critical test of global equity.","Climate finance":"John Dramani Mahama argues that developed nations must fulfill their overdue financial commitments to Africa through non-debt creating grants rather than loans.","Global health architecture":"John Dramani Mahama calls for building an equitable global health architecture with regional vaccine manufacturing and resilient infrastructure in the Global South, while emphasizing that African leaders must also ensure transparency, accountability, and fight corruption domestically.","Ghana economy":"John Dramani Mahama asserts that Ghana has achieved a dramatic economic recovery and sustained growth through disciplined governance, fiscal prudence, and anti-corruption efforts.","Ghana infrastructure":"John Dramani Mahama states that Ghana is implementing an aggressive national infrastructure agenda and economic policies to improve daily lives, bridge divides, and create jobs.","Ghana healthcare":"John Dramani Mahama describes the launch of a free primary health care program and a specialized medical trust fund as central components of Ghana's national reset to achieve sustainable development goals.","Ghana democracy":"John Dramani Mahama argues that democracy must provide tangible social benefits to citizens and describes Ghana as a beacon of constitutional democracy on the African continent.","African Union":"John Dramani Mahama states that Ghana intends to use its 2027 African Union chairmanship to champion continental integration, accelerate the African Continental Free Trade Area, and promote peace and security in Africa.","African liberation":"John Dramani Mahama asserts that Ghana's independence is meaningless without the total liberation of the African continent and calls for expanding this historic truth.","Global unity":"John Dramani Mahama argues that national freedom and prosperity depend on global justice and shared humanity, urging the assembly to build bridges rather than walls.","Ceremony":"John Dramani Mahama expresses gratitude and offers blessings to Ghana and the United Nations."},"claims":[{"t":52,"quote":"congratulate you, Mr. president on your election to preside over the 81st session of the United Nations General Assembly","topic":"UNGA session","kind":"fact"},{"t":83,"quote":"I also wish to commend outgoing UN Secretary General Antonio Guterres for his dedicated service to our world body over the last 10 years.","topic":"UN leadership","kind":"fact"},{"t":184,"quote":"I was born in a little town, Damangu, which was then a modest community in northern Ghana and is now the capital of the Savana region of my country.","topic":"Ghana history","kind":"fact"},{"t":194,"quote":"I was born to Mr. Emmanuel Adama Mahama of Ble and Madame Abiba Naba of Bunu both of blessed memory.","topic":"Ghana history","kind":"fact"},{"t":219,"quote":"I speak Gongja which is a Guan language. I speak tree and Ghan. I am fluent in Hower spoken across the West African savannah in the Sahil.","topic":"Ghanaian culture","kind":"fact"},{"t":228,"quote":"I understand somewhere and I speak English as my official language.","topic":"Ghanaian culture","kind":"fact"},{"t":281,"quote":"When belonging is weaponized by political expediency, it transforms into native nativism, chauvinism, xenophobia, and the dangerous prejudices that are extended to people who are deemed different from us.","topic":"Xenophobia","kind":"fact"},{"t":296,"quote":"It becomes the pretext for discrimination, for displacement, for persecution and war.","topic":"Xenophobia","kind":"fact"},{"t":346,"quote":"last year from this very podium, I made a solemn pledge on behalf of Africa and the global African diaspora to seek full international recognition of the transatlantic trafficking and racialized chat, enslavement of Africans as the gravest crime against humanity.","topic":"Transatlantic trafficking","kind":"self_credit"},{"t":394,"quote":"for centuries, this tragedy was rendered in the passive voice as though the millions of African men, women, and children just vanished into the shadows of time.","topic":"Transatlantic trafficking","kind":"fact"},{"t":417,"quote":"Their unpaid labor built the cities, industries, banking institutions, and empires of the modern western world.","topic":"Transatlantic slave trade","kind":"fact"},{"t":439,"quote":"Mr. President, on 25th March this year, the international day of remembrance of the victims of slavery and the transatlantic slave trade, Ghana had the honor of tableabling resolution 80/250 in this very August assembly.","topic":"Transatlantic slave trade","kind":"self_credit"},{"t":457,"quote":"123 nations voted to affirm this fundamental truth that the transatlantic slave trade and charter enslavement were the gravest crimes against humanity.","topic":"Transatlantic slave trade","kind":"number"},{"t":489,"quote":"That resolution was not a mere gesture. It was adopted because the structural legacies of those historic crimes continue to fuel systematic racism, economic marginalization, and a global financial architecture that is weighted against Africa and people of African","topic":"African reparations","kind":"fact"},{"t":523,"quote":"The Netherlands, Germany, and France have all made positive moves to join the conversation on reparatory justice.","topic":"African reparations","kind":"fact"},{"t":567,"quote":"Africa is home to 1.5 billion people, over 18% of humanity, and constitutes the largest regional voting block in this general assembly.","topic":"UN Security Council","kind":"fact"},{"t":578,"quote":"And yet, Africa rem remains without a single permanent seat on the United Nations Security Council.","topic":"UN Security Council","kind":"fact"},{"t":636,"quote":"Developing nations and the global south borrow at interest rates that are up to eight times higher than industrialized","topic":"UN Security Council reform","kind":"number"},{"t":645,"quote":"African and Caribbean nations struck by climate disasters are forced to take on crippling debts to rebuild from floods and droughts that they did not cause","topic":"UN Security Council reform","kind":"fact"},{"t":691,"quote":"Our continent possesses the world's youngest population, vast arable lands, unparalleled cultural vitality, and the critical minerals required to drive the global green energy transition.","topic":"African minerals","kind":"fact"},{"t":736,"quote":"The African continental free trade area whose secretariat Ghana is proud to host is our engine for intra African trade structural transformation and industrial growth.","topic":"African minerals","kind":"self_credit"},{"t":792,"quote":"And nowhere is this crisis of credibility more painful than in the ongoing persecution of the Palestinian people in Gaza and the West Bank.","topic":"Israel-Gaza","kind":"fact"},{"t":827,"quote":"The blood of 5-year-old Hind Rajab and the more than 20,000 children that have been killed in this brutal conflict cries out to the conscience of the Collective punishment and forced starvation and mass displacement are flagrant violations of international","topic":"Israel-Gaza","kind":"fact"},{"t":892,"quote":"decadesl long economic, commercial, and financial embargo that has been imposed on Cuba","topic":"Cuba","kind":"fact"},{"t":922,"quote":"catastrophic conflict in Sudan, which is reported to be the world's worst humanitarian crisis","topic":"Cuba","kind":"fact"},{"t":1000,"quote":"melting glaciers, flash flood, flooding, droughts, record-breaking heat waves, brush fires, hurricanes, and other extreme weather phenomena are unmistakable signs of an overburdened","topic":"Climate change","kind":"fact"},{"t":1016,"quote":"Climate change is the ultimate test of global equity.","topic":"Climate change","kind":"fact"},{"t":1020,"quote":"We in Africa contribute less than 4% of global greenhouse gases and yet we bear some of the heaviest burden of climate","topic":"Climate finance","kind":"number"},{"t":1041,"quote":"On 29th June this year, Ghana and coastal West Africa faced an unprecedented deluge. Torrential rain exceeding 160 mm was dumped on seven coastal regions of Ghana within 24 hours, resulting in 39 deaths and one still unaccounted for.","topic":"Climate finance","kind":"fact"},{"t":1086,"quote":"They just walk across without We must build an equitable global health architecture that guarantees regional manufacturing of vaccines and therapeutics, strengthen epidemic surveillance and funds resilient public health infrastructure across the global south in accordance with the demands of the Ara reset.","topic":"Global health architecture","kind":"fact"},{"t":1144,"quote":"Ghana is arguably the most stable democracy in Africa.","topic":"Global health architecture","kind":"fact"},{"t":1178,"quote":"Less than two years into my administration, through disciplined governance and fiscal prudence and an uncompromising fight against corruption, Ghana has achieved a dramatic economic Indeed, some circles describe it as a Ghanaian miracle.","topic":"Ghana economy","kind":"self_credit"},{"t":1195,"quote":"Our macroeconomic stabilization measures have restored growth, drastically reduced inflation, stabilized our national currency, and significantly lowered our public debt burden.","topic":"Ghana economy","kind":"fact"},{"t":1206,"quote":"This remarkable economic recover recovery story has been independently validated by all the multilateral financial institutions and major international credit rating agencies all of which affirm that Ghana has moved from economic vulnerability to sustained recovery, resilience and growth.","topic":"Ghana economy","kind":"fact"},{"t":1240,"quote":"we're pursuing an aggressive national infrastructure agenda under our big push program to build roads, expand digital connectivity, construct schools and health facilities.","topic":"Ghana infrastructure","kind":"fact"},{"t":1268,"quote":"Through our flagship 24-hour economy and accelerated exports development program and the soontobe launched new Ghana e economy policy, we're transforming Ghana into an industrial high productivity hub.","topic":"Ghana infrastructure","kind":"fact"},{"t":1311,"quote":"And so Ghana has officially launched a historic free primary health care program ensuring that every Gandhian can access essential primary health care services at their community level at zero cost.","topic":"Ghana healthcare","kind":"fact"},{"t":1325,"quote":"This program has been hailed by the World Health Organization and the United Nations as a benchmark paradigm shift for the global south and this model is currently being studied by other nations that are seeking to achieve true universal health coverage.","topic":"Ghana healthcare","kind":"fact"},{"t":1414,"quote":"In March 2027, Ghana will celebrate its 70th anniversary of independence as the first nation in subsaharan Africa to break the shackles of colonial domination.","topic":"Ghana democracy","kind":"fact"},{"t":1435,"quote":"And in January 2027, Ghana will proudly assume the chairmanship of the African","topic":"African Union","kind":"fact"},{"t":1544,"quote":"When our first president of Sajifu, Dr. Awami Kuma stood on the eve of our independence in 1957.","topic":"African liberation","kind":"fact"}],"promises":[{"t":723,"quote":"We will process our minerals at home. We will build local industries that create dignified jobs for our youth and we retain the value of our natural resources in Africa.","topic":"African minerals","kind":"promise"},{"t":1447,"quote":"I wish to serve notice that we intend to use our AU chairmanship to champion continental integration, accelerate the implementation of the African continental free trade area, push for peace and security in all the conflict zones of Africa, and ensure that Africa speaks on the global stage with one resolute, undivided and confident voice.","topic":"African Union","kind":"promise"}],"attacks":[{"t":867,"quote":"we condemn all acts of terrorism by Hamas that triggered this conflict","topic":"Israel-Gaza","target":"Hamas"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"UNGA session","text":"The assembly will now hear an address by his excellency John Ramani Mahama, President of the Republic of Ghana. I I request protocol to escort his excellency and invite him to address the Mr. President, Mr. Secretary General, your distinguished delegates, ladies and let me congratulate you, Mr. president on your election to preside over the 81st session of the United Nations General Assembly. You assume this solemn stewardship at a time of intense geopolitical deepening inequality and eroded trust in our multilateral system."},{"t":72,"topic":"UN leadership","text":"Ghana is confident that your proven commitment to inclusive, consultative and principled dialogue will guide this assembly well and you have our full I also wish to commend outgoing UN Secretary General Antonio Guterres for his dedicated service to our world body over the last 10 years. Mr. President, Ghana's national anthem contains a profound petition. It asked God to make us bold to defend forever the cause of freedom and of right. And those words gave my compatriots and I courage to uphold the Panaffrican and anticolonial heritage that was bequipped to us by our Another line in our item petitions God to fill our hearts with true humility and make us cherish fearless honesty. That prayer inspires me today to follow in the footsteps of Drwa Kruma, Hill Salassie, Nelson Mandela and other global icons who have stood at this very podium before me and have spoken boldly and fearlessly about the state of affairs in our world."},{"t":144,"topic":"Ghana history","text":"The words the world may not transform overnight because of the speeches that we deliver here in this August assembly, but history would faithfully record the truths we choose to speak and the silences that we choose to keep when we're granted the privilege of addressing this global town hall. Allow me therefore to begin by reintroducing myself to the general assembly. I stand before you as president of the Republic of Ghana. Yet we too often ascend these heights draped only in the ropes of our titles, forgetting that alongside each of us stands a history, a people, and a I was born in a little town, Damangu, which was then a modest community in northern Ghana and is now the capital of the Savana region of my country. I was born to Mr. Emmanuel Adama Mahama of Ble and Madame Abiba Naba of Bunu both of blessed memory. I belong to them and I belong to the four mothers and the forefathers who gave birth to them, who named them, who nurtured them and who passed down the enduring values by which I live today."},{"t":216,"topic":"Ghanaian culture","text":"I grew up at the crossroads of several Ghanaian cultures. I speak Gongja which is a Guan language. I speak tree and Ghan. I am fluent in Hower spoken across the West African savannah in the Sahil. I understand somewhere and I speak English as my official language. In a very real sense, I belong to all these people because their tongues including English have become my tongue. Language creates a kingship regardless of the historical complexities through which kinship was forged. Mr. President, everybody in this chamber today and every global citizen listening to my words possesses an origin. We carry inherited memories, values, rich cultures, and distinct identities of our Belonging anchors us and it reminds us that we are part of a human story that is far larger than ourselves. It is a vital wellspring of dignity and pride."},{"t":278,"topic":"Xenophobia","text":"But belonging also has its dark side. When belonging is weaponized by political expediency, it transforms into native nativism, chauvinism, xenophobia, and the dangerous prejudices that are extended to people who are deemed different from us. It becomes the pretext for discrimination, for displacement, for persecution and war. And yet for this organization, the United Nations, the founding principles remain immutable. Every human being belongs to the human No race is superior. No nation is inferior. No child, no child's life is worthless because of the language they speak or the faith they profess or the color of their skin or the land of their birth. This is the unyielding moral foundation upon which the United Nations must stand."},{"t":341,"topic":"Transatlantic trafficking","text":"I'll return to this issue of belonging at the end of my speech. But Mr. President, last year from this very podium, I made a solemn pledge on behalf of Africa and the global African diaspora to seek full international recognition of the transatlantic trafficking and racialized chat, enslavement of Africans as the gravest crime against humanity. Some cautioned that we were reopening old wounds. But we came not to provoke division or render empty judgment. We came to seek healing. And true healing requires truth. And truth requires acknowledgements. And acknowledgement must lead to meaningful repair. Mr. President, for centuries, this tragedy was rendered in the passive voice as though the millions of African men, women, and children just vanished into the shadows of time."},{"t":405,"topic":"Transatlantic slave trade","text":"Mr. President, they do not v vanish. They were hunted. They were captured. They were trafficked. They were bought. They were sold. They were exploited and exchanged for profit. They were ripped from their families and communities they belong to. Their unpaid labor built the cities, industries, banking institutions, and empires of the modern western world. Meanwhile, the African continent was left depopulated, split families, structural disruption, and generational trauma. Mr. President, on 25th March this year, the international day of remembrance of the victims of slavery and the transatlantic slave trade, Ghana had the honor of tableabling resolution 80/250 in this very August assembly. Mr. 123 nations voted to affirm this fundamental truth that the transatlantic slave trade and charter enslavement were the gravest crimes against humanity."},{"t":472,"topic":"African reparations","text":"I stand with respect at this p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p p podium to thank every nation that voted for justice and I'm deeply grateful to our brothers and sisters in the African Union, the CARICOM, Celac and our partners across the global south. That resolution was not a mere gesture. It was adopted because the structural legacies of those historic crimes continue to fuel systematic racism, economic marginalization, and a global financial architecture that is weighted against Africa and people of African Since the passage of the historic resolution, we welcome the positive overtures from many countries and institutions that have joined the dialogue on reparative justice. The Netherlands, Germany, and France have all made positive moves to join the conversation on reparatory justice. Mr. President, real repair demands structural transformation."},{"t":535,"topic":"UN Security Council","text":"It requires dismantling the persistent engines of exploitation, unfair global trade, predatory resource extraction, discriminated discriminatory credit ratings, unsustainable debt burdens of the global south, and the continued export of raw materials from Africa while real value addition and job creation occur elsewhere. Mr. President, the injustices of the past remain embedded in today's power Africa is home to 1.5 billion people, over 18% of humanity, and constitutes the largest regional voting block in this general assembly. And yet, Africa rem remains without a single permanent seat on the United Nations Security Council. This is fundamentally unacceptable in the 21st century. Africa must be granted permanent representation on the UN Security Council complete with all the rights and We cannot credibly champion the sovereign equality of nations while preserving a global governance structure that was designed for the post-war geopolitical realities."},{"t":614,"topic":"UN Security Council reform","text":"Mr. President, Security Council reform is not a favor to Africa. It is an imperative for the legitimacy, the credibility and the survival of the United Nations. The same systemic inequalities permeates the international financial Developing nations and the global south borrow at interest rates that are up to eight times higher than industrialized African and Caribbean nations struck by climate disasters are forced to take on crippling debts to rebuild from floods and droughts that they did not cause. Governments are forced into a tragic choice to service predatory debt or to serve their people. We demand reform. We need long-term affordable and accessible concessionary financing that enables developing economies to invest in human capital in industrialization and climate Mr."},{"t":678,"topic":"African minerals","text":"President, Africa does not seek charity. Africa seeks equal partnership that is anchored that is anchored in mutual respect. Our continent possesses the world's youngest population, vast arable lands, unparalleled cultural vitality, and the critical minerals required to drive the global green energy transition. But, Mr. let me warn Africa will not remain a passive arena for a new scramble for Critical mineral extraction in Africa must not replicate the colonial era We will process our minerals at home. We will build local industries that create dignified jobs for our youth and we retain the value of our natural resources in Africa. The African continental free trade area whose secretariat Ghana is proud to host is our engine for intra African trade structural transformation and industrial growth."},{"t":746,"topic":"Israel-Gaza","text":"As we heal historical wounds, we must address the alarming breakdown of the current global order. We are witnessing a dangerous shift towards unilateralism, lawlessness, and the erosion of multilateral norms. The United Nations must learn from the lessons of the League of Nations. The UN Charter must reign supreme over the cynical doctrine that might makes The veto power must never serve as a license for impunity. Sovereign equality cannot be a private privilege that is reserved only for nations that are aligned with global And nowhere is this crisis of credibility more painful than in the ongoing persecution of the Palestinian people in Gaza and the West Bank. Mr. Speaker, Mr."},{"t":807,"topic":"Israel-Gaza","text":"President, sorry I was an MP before. Mr. President, the time has come for us to stop using diplomatic euphemisms to ve the human carnage that is taking place in Gaza. How many more lives must be lost before the world acts with decisive moral author authority? The blood of 5-year-old Hind Rajab and the more than 20,000 children that have been killed in this brutal conflict cries out to the conscience of the Collective punishment and forced starvation and mass displacement are flagrant violations of international Ghana remains unwavering in its recognition of the sovereign state of Palestine and its steadfast support for a viable two-state solution where Israel and Palestine will live side by side in peace, security with guaranteed borders. At the same time, we condemn all acts of terrorism by Hamas that triggered this conflict and we insist that all parties unconditionally respect international humanitarian law."},{"t":878,"topic":"Cuba","text":"Our moral standards cannot be selective. In that spirit of international legality, in that same spirit international legality and human solidarity, Ghana reiterates its call for the immediate lifting of the decadesl long economic, commercial, and financial embargo that has been imposed on Cuba. The world must support Cuba's new economic and social program. Measures that inflict collective economic hardship on ordinary citizens run counter to our shared commitment to human dignity and international law. We must likewise elevate our global response to the catastrophic conflict in Sudan, which is reported to be the world's worst humanitarian crisis. We must also ex exercise solidarity with nations that are facing the ter terrorist scorge especially our neighbors in the alliance of Sahel The current Middle East crisis is having a deliterous effect on the world economy."},{"t":945,"topic":"Climate change","text":"We call for a return to the negotiating table and let me add that no human civilization deserves to be annihilated and certainly not a member of the United Nations. &gt;&gt; I believe that dialogue can resolve even the most intractable of global problems across every conflict whether in Europe, the Middle East, Africa. The standard must remain uniform, respect for sovereign integrity, protect civilians, ensure unhindered humanitarian access and hold perpetrators of war crimes &gt;&gt; Mr. President, those who have declared climate change a hoax perpetrated by geopolitical opponents, the warnings of recent times cannot have been clearer. melting glaciers, flash flood, flooding, droughts, record-breaking heat waves, brush fires, hurricanes, and other extreme weather phenomena are unmistakable signs of an overburdened Climate change is the ultimate test of global equity."},{"t":1020,"topic":"Climate finance","text":"We in Africa contribute less than 4% of global greenhouse gases and yet we bear some of the heaviest burden of climate We face erratic rainfall. Our coastal towns suffer relentless erosion. And our Sahilian region faces accelerating On 29th June this year, Ghana and coastal West Africa faced an unprecedented deluge. Torrential rain exceeding 160 mm was dumped on seven coastal regions of Ghana within 24 hours, resulting in 39 deaths and one still unaccounted for. And so climate justice demands that developed nations must fulfill their long overdue financial commitments. Mitigation support must be operationalized with predictable non-debt creating grants, not loans that further in debt fragile Similarly, global health security demands true solidarity because pathogens do not respect national borders."},{"t":1086,"topic":"Global health architecture","text":"They just walk across without We must build an equitable global health architecture that guarantees regional manufacturing of vaccines and therapeutics, strengthen epidemic surveillance and funds resilient public health infrastructure across the global south in accordance with the demands of the Ara reset. Mr. President, excellencies, I agree that even as we demand a place at the table and call for a more equitable and just global order as African leaders, we must also do what is required to put our own houses in order. As the legal maxim goes, whoever comes into equity must come with clean hands. African leadership must be transparent and accountable. We must commit to the fight against corruption and ensure that every dollar of our people's money counts and is used efficiently in their Ghana is arguably the most stable democracy in Africa."},{"t":1148,"topic":"Ghana economy","text":"We believe in the rule of law and have respect for human rights and we're determined to demonstrate that democracy works. While progress in a democracy may be slow because it must follow constitutional processes, it is more sustainable because it is built through popular participation and consensus As Ghana addresses these global imperatives, we are leading by example at home through our transformative resetting Ghana agenda. Less than two years into my administration, through disciplined governance and fiscal prudence and an uncompromising fight against corruption, Ghana has achieved a dramatic economic Indeed, some circles describe it as a Ghanaian miracle. Our macroeconomic stabilization measures have restored growth, drastically reduced inflation, stabilized our national currency, and significantly lowered our public debt burden. This remarkable economic recover recovery story has been independently validated by all the multilateral financial institutions and major international credit rating agencies all of which affirm that Ghana has moved from economic vulnerability to sustained recovery, resilience and growth."},{"t":1226,"topic":"Ghana infrastructure","text":"But Mr. President, macroeconomic indicators mean little if they do not translate into real improvements in our people's daily lives. Economic growth and progress must have a human face. And that is why we're pursuing an aggressive national infrastructure agenda under our big push program to build roads, expand digital connectivity, construct schools and health facilities. This strategic investment is opening up the length and breadth of our country, bridging the rural urban divide, unlocking agricultural potential, and guaranteeing equipable access to basic services for every Ghanaian, no matter where they live in our country. Through our flagship 24-hour economy and accelerated exports development program and the soontobe launched new Ghana e economy policy, we're transforming Ghana into an industrial high productivity hub. We're incentivizing roundthe-clock commercial operations, driving value addition in agriculture, mining, and creating sustainable dignified jobs for our vibrant youth and women."},{"t":1293,"topic":"Ghana healthcare","text":"And central to our national reset is a revolutionary expansion of social protection, universal healthcare, delivering on the sustainable development goals, specifically SDG1 on poverty, SDG3 on good health and well-being, and SDG10 on reduced inequalities. And so Ghana has officially launched a historic free primary health care program ensuring that every Gandhian can access essential primary health care services at their community level at zero cost. This program has been hailed by the World Health Organization and the United Nations as a benchmark paradigm shift for the global south and this model is currently being studied by other nations that are seeking to achieve true universal health coverage. Alongside our national health insurance scheme, we've introduced a specialized fund officially named Ghana Medical Trust Fund, but popularly referred to after my name, Mahhamare, that guarantees Ghanaians suffering from non-communicable diseases such as renal failure, cancers, cardiovascular diseases, and diabetes."},{"t":1362,"topic":"Ghana democracy","text":"It guarantees that they receive subsidized, affordable, and life-saving care. I've always believed that democracy must deliver tangible social benefits. Citizens must experience democracy not only through the ballot box every four years, but through improved access to food, quality education, decent housing, accessible health care, and economic Mr. President, democracy loses its soul when it protects elite privileges while abandoning the vulnerable. And so Ghana remains an uncompromising beacon of constitutional democracy, medium of freedom, the rule of law, and peaceful transitions of power on the African continent. But these domestic achievements set the stage for two historic milestones ahead of us. [snorts] In March 2027, Ghana will celebrate its 70th anniversary of independence as the first nation in subsaharan Africa to break the shackles of colonial domination."},{"t":1435,"topic":"African Union","text":"And in January 2027, Ghana will proudly assume the chairmanship of the African I wish to serve notice that we intend to use our AU chairmanship to champion continental integration, accelerate the implementation of the African continental free trade area, push for peace and security in all the conflict zones of Africa, and ensure that Africa speaks on the global stage with one resolute, undivided and confident voice. Mr. President, the doubting crisis confronting our world are not insurmountable. What we lack is not resources or intellect. What we lack is the political courage to see one another as a part of a single human family. We must see each other not as strategic rivals, economic targets or demographic threats, but as human beings who belong."},{"t":1499,"topic":"African liberation","text":"That refugee fleeing violence belongs. That migrant seeking opportunity That child in Gaza, Sudan or Ukraine The descendants of enslaved Africans seeking justice belong. The indigenous community protecting its ancestral lands and environment belongs. The small island state threatened by rising oceans belong to humanity. The poor, the vulnerable and the marginalized belong. They belong to our common human family. And because they belong, we must safeguard their dignity. We must enforce their rights. And most of all, we must hear their voices. When our first president of Sajifu, Dr. Awami Kuma stood on the eve of our independence in 1957. He declared that the independence of Ghana is meaningless unless it is linked up with the total liberation of the African continent. Today, from this respected global podium, we must expand that historic truth."},{"t":1568,"topic":"Global unity","text":"The freedom of any nation is insecure unless it is linked to the freedom of all humanity. In Ghana, we believe that our national prosperity is fragile unless it is a shared prosperity. Our global peace is unviable unless it is anchored in justice. Let this general assembly recommit itself to a world where belonging is used not to erect walls but to build bridges, not to exclude, but to unite, not to degrade humanity, but to exalt. Let us speak truth with humility. Let us act with courage. And as I said from the Gand National Anthem, let us cherish fearless honesty in the statements that we deliver today at this podium and in the choices we make tomorrow. May God bless our shared world."},{"t":1631,"topic":"Ceremony","text":"May God bless my homeland, Ghana. And may God bless the United Nations. I thank you. On behalf of the assembly, I wish to thank the President of the Republic of Ghana."}],"compare":[{"topic":"Africa","share":0.2008,"mean":0.0225,"rank":6,"others":36},{"topic":"UN & its reform","share":0.1756,"mean":0.2049,"rank":107,"others":170},{"topic":"Climate Change","share":0.0872,"mean":0.0426,"rank":37,"others":77},{"topic":"Israel–Palestine","share":0.0821,"mean":0.0522,"rank":47,"others":76},{"topic":"Cuba","share":0.0416,"mean":0.0112,"rank":21,"others":23},{"topic":"Transnational Crime","share":0.0393,"mean":0.0034,"rank":5,"others":4},{"topic":"International Law & Order","share":0.0393,"mean":0.0605,"rank":99,"others":102},{"topic":"Human Rights","share":0.0391,"mean":0.0084,"rank":22,"others":24}]};
